mapper.sql:
SELECT
id,
account,
name,
charge_id,
charge_name,
sales_org_id,
sales_org_name,
dict_area_code,
dict_country_code,
dict_country_code,
auth_status,
disabled,
auth_time,
customer_id,
domain,
country_name,
dict_platform,
create_user_name,
create_time,
update_user_name,
update_time,
si.extend_data
FROM shop_info si
WHERE ${params.sqlMap.default}
and si.is_deleted=FALSE

    AND si.name ILIKE concat('%',#{params.name}::text,'%')


    AND si.dict_platform =#{params.dictPlatform}


    AND si.account ILIKE concat('%',#{params.account}::text,'%')


    AND si.dict_country_code = #{params.dictCountryCode}


    AND si.disabled IN

        #{disabled}



    AND si.auth_status IN

        #{authStatus}



    AND si.create_user_id IN

        #{createUserId}



    AND si.sales_org_id IN

        #{salesOrgId}



    AND si.update_user_id IN

        #{updateUserId}



    AND si.create_time >= #{params.createTimeList[0]}
    AND si.create_time <= #{params.createTimeList[1]}



    AND si.update_time >= #{params.updateTimeList[0]}
    AND si.update_time <= #{params.updateTimeList[1]}


    AND si.auth_time >= #{params.authTimeList[0]}
    AND si.auth_time <= #{params.authTimeList[1]}



    ${params.permissionSql}

ORDER BY
si.update_time DESC

mapper.select:
select dict_area_code from shop_info si
si.is_deleted = false
and si.dict_area_code = #{params.searchKeyword}
and si.dict_platform = #{params.dictPlatform}
group by dict_area_code order by dict_area_code desc
